          position: {
            knob: 'number',
            defaultValue: -90,
            min: -180,
            max: 180,
            step: 10,
          },
          radiusTickNumber: { knob: 'number', defaultValue: 3, min: 0, max: 20 },
          startAngle: {
            knob: 'number',
            defaultValue: -90,
            min: -360,
            max: 400,
            step: 10,
          },
          endAngle: {
            knob: 'number',
            defaultValue: 90,
            min: -360,
            max: 400,
            step: 10,
          },
          minRadius: { knob: 'number', defaultValue: 30, min: 0, step: 10 },
          maxRadius: { knob: 'number', defaultValue: 130, min: 50, step: 10 },
